def distract(n, lo, hi, seed, k=2):
    r = random.Random(seed); c = [x for x in range(max(lo, n - 3), min(hi, n + 3) + 1) if x != n]; r.shuffle(c); return [str(x) for x in c[:k]]
def counts(seed, nums, icons):
    return [Q('كم عدد الأشياء في الصورة؟', str(n), distract(n, 1, 10, seed + n), 'العدد الصحيح هو ' + W[n] + '.', cnt=(icons[i % len(icons)], n)) for i, n in enumerate(nums)]
